import {create3DScene,bind3DInput} from '../../js/3d/index.js';
import {rigFromTo} from '../../js/3d/attachments.js';
import {Battle3D,WAR_UNITS,weaponPose} from '../../js/wars3d-core.js';
import {WAR_WEAPONS,DEFEAT_TIMING} from '../../js/wars3d-weapons.js';
import {createWarScene} from '../../js/wars3d-scene.js';
import {WAR_LIGHTING} from '../../js/wars3d-environment.js';
const $=s=>document.querySelector(s);let runtime,view,input,model,hero,elapsed=0,token=0,helpers=[],axisParents=[],override={};
$('#unit').innerHTML=WAR_UNITS.map(u=>`<option value="${u.id}">${u.name}</option>`).join('');
function sync(){const cfg=WAR_WEAPONS[$('#unit').value];$('#hand').value=cfg.socket;for(const el of document.querySelectorAll('[data-offset]')){const field=el.dataset.offset,at=+el.dataset.axis;el.value=String(cfg.grip[field][at]*(field==='rotation'?180/Math.PI:1));}readOffsets();}
function readOffsets(){override={socket:$('#hand').value,grip:{position:[0,0,0],rotation:[0,0,0],pivot:[0,0,0],scale:1}};for(const el of document.querySelectorAll('[data-offset]'))override.grip[el.dataset.offset][+el.dataset.axis]=(+el.value||0)*(el.dataset.offset==='rotation'?Math.PI/180:1);if(hero)hero.weaponOverride=override;$('#config').value=JSON.stringify({unit:$('#unit').value,...override},null,2);}
function segment(name,color,parent=null){const {B,scene}=runtime,m=B.MeshBuilder.CreateCylinder(name,{height:1,diameter:.012,tessellation:4},scene),mat=new B.StandardMaterial(name+'-material',scene);mat.diffuseColor=B.Color3.FromHexString(color);mat.emissiveColor=mat.diffuseColor.scale(.5);m.material=mat;m.parent=parent;m.isPickable=false;helpers.push(m);return m;}
function line(mesh,a,b){const {B}=runtime,d=b.subtract(a);mesh.position.copyFrom(a.add(b).scale(.5));mesh.scaling.y=d.length();mesh.rotationQuaternion=B.Quaternion.FromArray(rigFromTo({x:0,y:1,z:0},d));}
function axes(parent){const {B}=runtime;for(const[direction,color]of [[[.3,0,0],'#eb6860'],[[0,.3,0],'#80cf7b'],[[0,0,.3],'#659ce1']])line(segment('local-axis',color,parent),B.Vector3.Zero(),new B.Vector3(...direction));}
function preview(dt){if(!hero)return;const animate=$('#animate').checked;elapsed+=animate?dt:0;const state=$('#state').value,progress=animate?elapsed%1:+$('#phase').value;Object.assign(hero,{state:state==='block'?'idle':state,blockUntil:state==='block'?1e6:0,attack:state==='attack'?{progress}:null,walk:elapsed*5,alive:state!=='dead',deadAt:0,weaponOverride:override,unarmed:$('#unarmed').checked,hurtAt:$('#reaction').checked?elapsed-.05:-Infinity});model.clock=elapsed;if(state==='dead'&&!animate){const a=view.getActor(hero.id);if(a)a.deathAge=progress*DEFEAT_TIMING.remove;}}
async function start(){const next=++token;$('#start').disabled=true;input?.dispose();view?.dispose();runtime?.dispose();runtime=view=input=null;helpers=[];axisParents=[];elapsed=0;$('#info').textContent='Loading the actual soldier, Havok and equipment…';try{const r=await create3DScene($('#canvas'),{quality:'low',lighting:WAR_LIGHTING,camera:{radius:4.6,minRadius:2,maxRadius:15,target:[0,1,0]},onError:e=>$('#info').textContent=e.message});if(next!==token){r.dispose();return;}runtime=r;model=new Battle3D({mode:'sandbox',field:9,budget:1000});model.place($('#unit').value,-1.7,0);if($('#mode').value==='duel')model.place('guard',1.7,0,1);else model.place('club',8,5,1);model.start();hero=model.units[0];hero.scale=+$('#size').value;hero.radius=.36*hero.scale;hero.weaponOverride=override;if($('#mode').value!=='duel'){hero.x=0;hero.z=0;hero.angle=0;model.units=[hero];model.phase='inspection';}const v=await createWarScene(r,model);if(next!==token){v.dispose();r.dispose();return;}view=v;preview(0);view.update(.2);const {B}=r,actor=view.getActor(hero.id);for(const socket of ['right','left']){const anchor=actor.equipment.attachments.anchors.get(socket);axes(anchor);axisParents.push(anchor);}const hit=segment('actual-hit-segment','#e9c779'),muzzle=B.MeshBuilder.CreateSphere('release-point',{diameter:.075,segments:5},r.scene);muzzle.material=new B.StandardMaterial('release-material',r.scene);muzzle.material.emissiveColor=B.Color3.FromHexString('#6ce9e7');helpers.push(muzzle);
 input=bind3DInput($('#canvas'),r,{cameraMode:()=>true});r.setUpdate(dt=>{if($('#mode').value==='duel'){model.update($('#animate').checked?dt:0);}else preview(dt);view.update($('#animate').checked?dt:($('#mode').value==='preview'&&$('#state').value==='dead'?.05:0));const frame=weaponPose({...hero,clock:model.clock,deathAge:view.getActor(hero.id)?.deathAge||0,block:model.clock<hero.blockUntil}),a=view.getActor(hero.id);if(a){if($('#mode').value==='preview'){a.equipment.root.setEnabled(!hero.unarmed);a.equipment.shield?.setEnabled(!hero.unarmed);}if($('#mode').value==='preview')a.bar.setEnabled(false);line(hit,new B.Vector3(frame.root.x,frame.root.y,frame.root.z),new B.Vector3(frame.tip.x,frame.tip.y,frame.tip.z));muzzle.position.set(frame.muzzle.x,frame.muzzle.y,frame.muzzle.z);}for(const h of helpers)h.setEnabled($('#axes').checked&&!!a);const grip=a?.equipment.attachments.point(frame.config.socket);$('#info').textContent=`${r.software?'SOFTWARE 3D · GPU appearance unverified':'WEBGL'} · ${hero.type} · ${hero.state} · ${hero.scale}×\n${$('#mode').value==='duel'?`Actual combat · ${model.clock.toFixed(2)}s · ${model.done?'COMPLETE':'RUNNING'}`:'Preview · phase '+(hero.attack?.progress??+$('#phase').value).toFixed(2)}\nGrip ${grip?[grip.x,grip.y,grip.z].map(v=>v.toFixed(3)).join(', '):'released'} · support error ${Math.max(...Object.values(frame.errors)).toFixed(4)}m\nHP ${hero.hp.toFixed(0)} · hits received ${hero.damageTaken||0} · ${$('#reaction').checked?'normal-hit overlay · ':''}14-joint soldier · wrist sockets · ${frame.config.twoHanded||frame.config.animation==='bow'?'two hands':'one hand'} · ${r.stats().fps} measured FPS`;});r.pause(false);$('#message').textContent=r.software?'Compatibility rendering: actual rigs and geometry are running; GPU lighting and physical Windows touch still require hardware checks.':'Actual game assets are running. Orbit around the grip, or use the four camera views.';
 }catch(e){$('#info').textContent='Could not start: '+e.message;}finally{if(next===token)$('#start').disabled=false;}}
$('#start').onclick=start;$('#unit').onchange=()=>{sync();if(runtime)start();};for(const id of ['size','mode','state'])$('#'+id).onchange=()=>{if(runtime)start();};$('#hand').onchange=readOffsets;document.querySelectorAll('[data-offset]').forEach(n=>n.oninput=readOffsets);$('#reset').onclick=sync;$('#export').onclick=()=>{const blob=new Blob([$('#config').value],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wars-'+$('#unit').value+'-grip.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{if(!runtime)return;const [alpha,beta]={front:[Math.PI/2,.9],side:[0,.9],rear:[-Math.PI/2,.9],overhead:[Math.PI/2,.12]}[b.dataset.camera];runtime.camera.alpha=alpha;runtime.camera.beta=beta;});$('#step').onclick=()=>{if(!runtime)return;$('#animate').checked=false;elapsed+=1/60;if($('#mode').value==='duel')model.update(1/60);else{hero.attack??={progress:+$('#phase').value};$('#phase').value=String(Math.min(1,+$('#phase').value+1/60));preview(0);}view.update(1/60);};
window.addEventListener('pagehide',()=>{token++;input?.dispose();view?.dispose();runtime?.dispose();});sync();
